import { WaterfallChart } from '@dreadnought/ui/react';
const data = [{ id: 'start', label: 'Начало', kind: 'start', value: 100 }, { id: 'income', label: 'Доход', kind: 'change', value: 40 }, { id: 'subtotal', label: 'Подытог', kind: 'total' }, { id: 'cost', label: 'Расходы', kind: 'change', value: -25 }, { id: 'total', label: 'Остаток', kind: 'total' }] as const;
export function Example() { return <WaterfallChart label="Бюджет" data={data} />; }

import { WaterfallChart, useWaterfallChart } from '@dreadnought/ui/react';
const data = [{id:'a',label:'Начало',kind:'start',value:100},{id:'b',label:'Расход',kind:'change',value:-25},{id:'c',label:'Итог',kind:'total'}] as const;
function Controls() { const {page} = useWaterfallChart(); return <button disabled={page.page === page.count} onClick={() => page.change(page.page + 1)}>Следующая страница</button>; }
export function Example() { return <WaterfallChart label="Данные" data={data} pageSize={1}><Controls /><WaterfallChart.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</WaterfallChart.Plot><WaterfallChart.Table /><WaterfallChart.Pagination /><WaterfallChart.Empty /></WaterfallChart>; }
